&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : Codex Monstrueux p.97&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;PX&lt;/b&gt; 9600
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Gobelours.html&quot; title=&quot;Gobelours&quot;&gt;Gobelours&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Ninja.html&quot; title=&quot;Le ninja&quot;&gt;ninja&lt;/a&gt; 5/ &lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Ombres.html&quot; title=&quot;Le ma&#238;tre des ombres&quot;&gt;ma&#238;tre des ombres&lt;/a&gt; 4 (&lt;i&gt;Arts de la guerre&lt;/i&gt; p.9)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Type-Humano&#239;de.html&quot; title=&quot;Humano&#239;de&quot;&gt;Humano&#239;de&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Gobelino&#239;de.html&quot; title=&quot;Gobelino&#239;de (sous-type)&quot;&gt;gobelino&#239;de&lt;/a&gt;) de taille M, CM
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Init&lt;/b&gt; +4 ; &lt;b&gt;Sens&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;vision dans le noir&quot;&gt;vision dans le noir&lt;/a&gt; 18 m (12 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;), &lt;a class=&quot;pagelink&quot; href=&quot;Odorat-(Capacit&#233;).html&quot; title=&quot;odorat&quot;&gt;odorat&lt;/a&gt; ; &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +15
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;D&#233;fense&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;CA&lt;/b&gt; 25, contact 16, pris au d&#233;pourvu 20 (armure +4, Dex +4, esquive +1, naturelle +5, parade +1)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;pv&lt;/b&gt; 82 (12d8+29)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;R&#233;f&lt;/b&gt; +14, &lt;b&gt;Vig&lt;/b&gt; +6, &lt;b&gt;Vol&lt;/b&gt; +4
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Capacit&#233;s d&#233;fensives&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Ninja.html#ESQUIVEINSTINCTIVESUP&#201;RIEURE&quot; title=&quot;Le ninja&quot;&gt;esquive instinctive sup&#233;rieure&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Ombres.html#ESQUIVETOTALE&quot; title=&quot;Le ma&#238;tre des ombres&quot;&gt;esquive totale&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Attaque&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;VD&lt;/b&gt; 9 m (6 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Corps &#224; corps&lt;/b&gt; &lt;i&gt;&#233;p&#233;e courte +1&lt;/i&gt;, +15/+10 (1d6+6/17-20) ou dague de ma&#238;tre, +13/+8 (1d4+5/19-20)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Distance&lt;/b&gt; dague de ma&#238;tre, +12 (1d4+5/19-20))
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Ninja.html#ATTAQUESOURNOISE&quot; title=&quot;Le ninja&quot;&gt;attaque sournoise&lt;/a&gt; +3d6
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Pouvoirs magiques de ma&#238;tre des ombres&lt;/b&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; 4 ; &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;Concentration&quot;&gt;concentration&lt;/a&gt; +5)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
2/jour — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Ombres.html#OMBRESILLUSOIRES&quot; title=&quot;Le ma&#238;tre des ombres&quot;&gt;ombres illusoires&lt;/a&gt;&lt;/i&gt; (DD 11)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
1/jour — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Ombres.html#CONVOCATIONDOMBRE&quot; title=&quot;Le ma&#238;tre des ombres&quot;&gt;convocation d’ombre&lt;/a&gt;&lt;/i&gt; (DD 15)
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Tactique&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Avant le combat.&lt;/b&gt; L&#39;ombre discr&#232;te utilise la discr&#233;tion totale pour tendre une embuscade &#224; son adversaire.
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Caract&#233;ristiques&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;For&lt;/b&gt; 20, &lt;b&gt;Dex&lt;/b&gt; 18, &lt;b&gt;Con&lt;/b&gt; 14, &lt;b&gt;Int&lt;/b&gt; 8, &lt;b&gt;Sag&lt;/b&gt; 10, &lt;b&gt;Cha&lt;/b&gt; 12
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;BBA&lt;/b&gt; +8, &lt;b&gt;BMO&lt;/b&gt; +13, &lt;b&gt;DMD&lt;/b&gt; 29
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Dons&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Arme-De-Pr&#233;dilection.html&quot; title=&quot;Arme de pr&#233;dilection&quot;&gt;Arme de pr&#233;dilection&lt;/a&gt; (&#233;p&#233;e courte), &lt;a class=&quot;pagelink&quot; href=&quot;Attaques-R&#233;flexes.html&quot; title=&quot;Attaques r&#233;flexes&quot;&gt;Attaques r&#233;flexes&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Esquive.html&quot; title=&quot;Esquive&quot;&gt;Esquive&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Ki-Suppl&#233;mentaire.html&quot; title=&quot;Ki suppl&#233;mentaire&quot;&gt;Ki suppl&#233;mentaire&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Critique.html&quot; title=&quot;Science du critique&quot;&gt;Science du critique&lt;/a&gt; (&#233;p&#233;e courte), &lt;a class=&quot;pagelink&quot; href=&quot;Souplesse-Du-Serpent.html&quot; title=&quot;Souplesse du serpent&quot;&gt;Souplesse du serpent&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; +19, &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; +23, &lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt; +20,  &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; +5, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +15, &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt; (danse) +6, &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt; +11
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Langues&lt;/b&gt; commun, gobelin
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Particularit&#233;s&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Ninja.html#ASTUCEDENINJA&quot; title=&quot;Le ninja&quot;&gt;astuce de ninja&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Talents.html#DEBOUT&quot; title=&quot;Les talents de roublard&quot;&gt;debout&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Astuces.html#DISCRETETRAPIDE&quot; title=&quot;Les astuces de ninja&quot;&gt;discret et rapide&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Ombres.html#CONVOCATIONDOMBRE&quot; title=&quot;Le ma&#238;tre des ombres&quot;&gt;convocation d’ombre&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Ombres.html#DISCRETIONTOTALE&quot; title=&quot;Le ma&#238;tre des ombres&quot;&gt;discr&#233;tion totale&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Ninja.html#PASDETRACE&quot; title=&quot;Le ninja&quot;&gt;pas de trace&lt;/a&gt; +1, &lt;a class=&quot;pagelink&quot; href=&quot;Ninja.html#R&#201;SERVEDEKI&quot; title=&quot;Le ninja&quot;&gt;r&#233;serve de ki&lt;/a&gt; (5), &lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Ombres.html#POUVOIRDEROUBLARD&quot; title=&quot;Le ma&#238;tre des ombres&quot;&gt;talent de roublard&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Talents.html#REACTIONSLENTES&quot; title=&quot;Les talents de roublard&quot;&gt;r&#233;actions lentes&lt;/a&gt;), &lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Ombres.html#TELEPORTATIONPARLESOMBRES&quot; title=&quot;Le ma&#238;tre des ombres&quot;&gt;t&#233;l&#233;portation par les ombres&lt;/a&gt; (12 m/jour), &lt;a class=&quot;pagelink&quot; href=&quot;Gobelours.html#TRAQUEUR&quot; title=&quot;Gobelours&quot;&gt;traqueur&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Ninja.html#UTILISATIONDUPOISON&quot; title=&quot;Le ninja&quot;&gt;utilisation du poison&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;&#201;quipement divers&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armure-De-Cuir-(Armure).html&quot; title=&quot;Armure de cuir&quot;&gt;armure de cuir +2&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;p&#233;e-Courte-(Arme).html&quot; title=&quot;&#201;p&#233;e courte&quot;&gt;&#233;p&#233;e courte +1&lt;/a&gt;&lt;/i&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Dague-(Arme).html&quot; title=&quot;Dague&quot;&gt;dagues de ma&#238;tre&lt;/a&gt; (3), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-Darmure-Naturelle.html&quot; title=&quot;Amulette d&amp;#39;armure naturelle&quot;&gt;amulette d&#39;armure naturelle +1&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-R&#233;sistance.html&quot; title=&quot;Cape de r&#233;sistance&quot;&gt;cape de r&#233;sistance +1&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Anneau-De-Protection.html&quot; title=&quot;Anneau de protection&quot;&gt;anneau de protection +1&lt;/a&gt;&lt;/i&gt;, 374po
&lt;/div&gt;
&lt;/div&gt;
&lt;/td&gt;&lt;td&gt;&lt;div&gt;&lt;div style=&quot;float:right; background-color: #fff; padding: 0 0 0 0; margin: 0 0 4px 8px&quot;&gt; 
&lt;table CLASS=&quot;tablo autoalt&quot;&gt;&lt;caption&gt;Variantes de gobelours&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Nom&lt;/td&gt;&lt;td&gt;FP&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gobelours.html&quot; title=&quot;Gobelours&quot;&gt;Gobelours&lt;/a&gt;&lt;/td&gt;&lt;td&gt;2&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Grincedent-Gobelours.html&quot; title=&quot;Grincedent gobelours&quot;&gt;Grincedent gobelours&lt;/a&gt;&lt;/td&gt;&lt;td&gt;4&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Traqueur-Gobelours.html&quot; title=&quot;Traqueur gobelours&quot;&gt;Traqueur gobelours&lt;/a&gt;&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fanatique-Gobelours.html&quot; title=&quot;Fanatique gobelours&quot;&gt;Fanatique gobelours&lt;/a&gt;&lt;/td&gt;&lt;td&gt;7&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;voreur-Gobelours.html&quot; title=&quot;D&#233;voreur gobelours&quot;&gt;D&#233;voreur gobelours&lt;/a&gt;&lt;/td&gt;&lt;td&gt;8&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur-Gobelours.html&quot; title=&quot;R&#244;deur gobelours&quot;&gt;R&#244;deur gobelours&lt;/a&gt;&lt;/td&gt;&lt;td&gt;8&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Spectre-Terrifiant.html&quot; title=&quot;Spectre terrifiant&quot;&gt;Spectre terrifiant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;8&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gobelours-Adepte-De-Lembuscade.html&quot; title=&quot;Gobelours adepte de l&amp;#39;embuscade&quot;&gt;Gobelours adepte de l&#39;embuscade&lt;/a&gt;&lt;/td&gt;&lt;td&gt;10&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ombre-Discr&#232;te-Gobelours.html&quot; title=&quot;Ombre discr&#232;te gobelours&quot;&gt;Ombre discr&#232;te gobelours&lt;/a&gt;&lt;/td&gt;&lt;td&gt;10&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mage-Du-Sang-Gobelours.html&quot; title=&quot;Mage du sang gobelours&quot;&gt;Mage du sang gobelours&lt;/a&gt;&lt;/td&gt;&lt;td&gt;11&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tyran-Gobelours.html&quot; title=&quot;Tyran gobelours&quot;&gt;Tyran gobelours&lt;/a&gt;&lt;/td&gt;&lt;td&gt;13&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt; Les gobelours aiment la chair des &#234;tres intelligents, mais ils pr&#233;f&#232;rent g&#233;n&#233;ralement manger d&#39;autres esp&#232;ces plut&#244;t que la leur. Ils conservent souvent des groupes de captifs pendant des semaines, les tuants et les d&#233;vorant un par un.
&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
